// Workspace MCP — shared auth context, helpers, and output shapes used by the tool modules.
// Generated by splitting [[...transport]]/route.ts; keep edits here, not in the tool modules.
import { startBackgroundOperation } from "@/lib/infrastructure/global-mcp-operations"
import { db, getTenantDb } from "@/lib/database"
import { createHash } from "crypto"
import { AsyncLocalStorage } from "async_hooks"
import { getDeploymentStatus, getLatestDeployment } from "@/lib/vercel-client"
import { findOrClaimByIdempotencyKey, isIdempotencyClaimStillInFlight, type McpBuildRunRecord } from "@/lib/infrastructure/mcp-build-run"
import { matchesSignature } from "@/lib/infrastructure/deployment-source-guard"
import { safeFetch } from "@/lib/safe-url"
import { type EntryWriteContext, type ContentActor } from "@/lib/content/entry-service"
import { isTenantPlanPaid } from "@/lib/infrastructure/hosting-plan"
import type { createMcpHandler } from "mcp-handler"

// The server object createMcpHandler hands to the factory.
export type McpServer = Parameters<Parameters<typeof createMcpHandler>[0]>[0]

export interface AuthContext {
  tenantId: string
  tenantSlug: string
  tenantName: string
  permissions: string[]
  plan: string
  isPaid: boolean
  /** Narrower than `isPaid` — true only on an actual paid plan tier (or
   *  active hosting payment), excludes Free. Gates the Vercel-hosting
   *  tools specifically; `isPaid` gates general MCP access and is
   *  deliberately true for Free tier too. */
  isHostingPlanPaid: boolean
  isSuperAdmin?: boolean
  paymentError?: string
}

export const authContext = new AsyncLocalStorage<AuthContext>()

export async function resolveToken(rawToken: string): Promise<AuthContext | null> {
  if (!rawToken?.trim()) return null
  const clean = rawToken.trim()
  const hashed = createHash("sha256").update(clean).digest("hex")

  let tenantData: { id: string; slug: string; name: string; plan: string; status: string; hostingStatus: string | null } | null = null
  let permissions: string[] = ["read", "write", "delete"]

  // MCP is a separate credential system from REST/GraphQL (see public-api-actor.ts).
  // Only type "mcp" ApiToken rows authenticate here; the legacy ApiKey (REST-only)
  // is not accepted. Lookup is by hash only: production had zero plaintext rows
  // of any token type when the plaintext fallback was removed (checked 2026-11-24).
  const token = await db.apiToken.findFirst({
    where: {
      token: hashed,
      type: "mcp",
    },
    select: {
      id: true,
      tenantId: true,
      permissions: true,
      expiresAt: true,
      tenant: { select: { id: true, slug: true, name: true, plan: true, status: true, hostingStatus: true } }
    },
  })

  // Tokens are minted with a 90-day expiresAt that this route never checked,
  // so an expired token kept working indefinitely.
  if (token?.expiresAt && token.expiresAt.getTime() <= Date.now()) return null

  if (token?.tenant) {
    db.apiToken.updateMany({
      where: { token: hashed, type: "mcp" },
      data: { lastUsedAt: new Date() }
    }).catch(() => {})

    tenantData = token.tenant
    if (Array.isArray(token.permissions)) {
      permissions = token.permissions as string[]
    }
  }

  if (!tenantData) return null

  // ─── Payment Status & Active Subscription Check ────────────────────────────
  // This `isPaid`/`paymentError` pair gates the WHOLE MCP connection (see
  // handleMcpRequest below) — it's an account-good-standing check, not a
  // plan-tier check, so a Free-plan tenant (its own Subscription row is
  // created with status "active" — see actions/tenant.ts) correctly passes
  // it: Free tier is intentionally free, not delinquent, and MCP's
  // schema/content tools are available to every plan. Only a genuinely
  // lapsed/cancelled subscription should trip this.
  const activeSubscription = await db.subscription.findFirst({
    where: {
      tenantId: tenantData.id,
      status: { in: ["active", "paid", "trialing"] }
    }
  })

  const isPaid = (tenantData.status === "active" && !!activeSubscription) || tenantData.hostingStatus === "active"
  let paymentError: string | undefined = undefined

  if (!isPaid) {
    paymentError = `❌ Payment Required: Akses MCP dinonaktifkan untuk workspace '${tenantData.slug}'. Status langganan Anda belum aktif/dibayar (status: ${activeSubscription?.status || "unpaid"}). Silakan aktifkan pembayaran melalui dashboard workspace.`
  }

  // Separate, narrower check for the Vercel-hosting tools specifically
  // (deploy_to_sacms, configure_deployment_domain, add_deployment_env,
  // make_deployment_public) — these must exclude Free tier, unlike the
  // general `isPaid` above. Confirmed live: `isPaid` above was always true
  // for Free tenants too, so the 4 individual `if (!auth.isPaid)` checks
  // inside those tool handlers never actually blocked anyone — this plan-
  // slug check (same helper the dashboard's own deploy route already
  // gates on) is the real fix.
  const isHostingPlanPaid = isTenantPlanPaid(tenantData.plan) || tenantData.hostingStatus === "active"

  return {
    tenantId: tenantData.id,
    tenantSlug: tenantData.slug,
    tenantName: tenantData.name,
    permissions,
    plan: tenantData.plan,
    isPaid,
    isHostingPlanPaid,
    isSuperAdmin: false,
    paymentError,
  }
}

export const UNAUTHORIZED = {
  content: [{
    type: "text" as const,
    text: "❌ Unauthorized: Invalid or missing API token. Please provide a valid Bearer token for your SaCMS workspace."
  }]
}

/**
 * Resolves the label to attach as this tenant's public
 * `*.sites.sacms.cloud` subdomain for a deploy triggered through this MCP
 * server — a tenant's own randomly-generated publicSubdomainToken when one
 * exists (every tenant created since that feature shipped), else its plain
 * slug. Deliberately READ-ONLY — never generates a token for a tenant that
 * doesn't already have one, unlike ensurePublicSubdomainToken (which only
 * runs at tenant creation/demo self-heal) — an ordinary deploy of an
 * existing tenant must never silently change its public URL.
 */
export async function resolveSubdomainLabel(tenantId: string, tenantSlug: string): Promise<string> {
  const tenant = await db.tenant.findUnique({ where: { id: tenantId }, select: { publicSubdomainToken: true } })
  return tenant?.publicSubdomainToken || tenantSlug
}

/**
 * Scope enforcement for API tokens.
 *
 * `AuthContext.permissions` was resolved from the token's own `permissions`
 * array (e.g. a token minted as read-only: `["read"]`) but was previously
 * only ever *read* by the `inspect_api_capabilities` tool to describe what a
 * token could do — no write/delete/schema/webhook tool actually checked it,
 * so a read-only token could still call `delete_content_type` and every
 * other mutating tool. Every mutating/schema/webhook tool now calls
 * `hasScope()` right after its `UNAUTHORIZED` check.
 *
 * `full_access` or `isSuperAdmin` bypasses all scopes, matching the
 * `can*` booleans already computed in `inspect_api_capabilities`.
 */
export type Scope = "read" | "write" | "delete" | "schema" | "webhooks" | "env"

export function hasScope(auth: AuthContext, scope: Scope): boolean {
  if (auth.isSuperAdmin) return true
  if (auth.permissions.includes("full_access")) return true
  return auth.permissions.includes(scope)
}

export function permissionDenied(scope: Scope) {
  const howToGrant = `Ask a workspace admin to grant it under Developer & API → API Tokens, or use a token with "full_access".`
  return {
    content: [{
      type: "text" as const,
      text: `❌ Forbidden: this API token does not have the "${scope}" permission. ${howToGrant}`
    }],
    isError: true,
  }
}

// ─── Webhook response shaping ───────────────────────────────────────────────
// The signing secret must never round-trip back out of any tool — a reader
// (or a trivial update that doesn't even touch the secret) could otherwise
// recover it and forge validly-signed requests to the tenant's receiving
// endpoint. `hasSecret` tells the caller whether one is configured without
// exposing its value, matching how API tokens are handled elsewhere in this
// file (shown once at creation/rotation, never again on plain reads).
export function redactWebhook(w: {
  id: string; name: string; url: string; events: unknown; enabled: boolean
  hookType: string; secret: string | null; failureCount: number
  lastTriggeredAt: Date | null; createdAt: Date
}) {
  return {
    id: w.id,
    name: w.name,
    url: w.url,
    events: w.events,
    enabled: w.enabled,
    hookType: w.hookType,
    hasSecret: !!w.secret,
    failureCount: w.failureCount,
    lastTriggeredAt: w.lastTriggeredAt,
    createdAt: w.createdAt,
  }
}

// ─── Deployment project ownership ───────────────────────────────────────────
/**
 * Resolves the Vercel project this tenant's own deployment lives under, and
 * rejects outright if the caller supplied a DIFFERENT project id. `projectId`
 * used to be passed straight through to Vercel's API with no check that it
 * actually belonged to the calling tenant — any tenant that knew (or
 * guessed — Vercel project ids aren't secret) another tenant's project id
 * could attach an attacker-controlled domain to it, overwrite one of its env
 * vars, or lift its deployment protection, none of which touch this app's
 * own Prisma-level tenant scoping since they're calls straight through to
 * Vercel's API under a single shared platform token.
 */
export async function resolveOwnProjectId(
  auth: AuthContext,
  suppliedProjectId: string | undefined,
): Promise<{ ok: true; projectId: string } | { ok: false; response: { content: { type: "text"; text: string }[]; isError: true } }> {
  const tenant = await db.tenant.findUnique({
    where: { id: auth.tenantId },
    select: { vercelProjectId: true },
  })
  let ownProjectId = tenant?.vercelProjectId || undefined
  if (!ownProjectId) {
    const row = await db.setting.findFirst({ where: { key: `${auth.tenantId}_vercelProjectId` } })
    ownProjectId = row?.value || undefined
  }

  if (!ownProjectId) {
    return {
      ok: false,
      response: {
        content: [{
          type: "text",
          text: "❌ Tidak ada Deployment Project ID. Deploy dulu dengan deploy_to_sacms, atau berikan parameter projectId.",
        }],
        isError: true,
      },
    }
  }

  if (suppliedProjectId && suppliedProjectId !== ownProjectId) {
    return {
      ok: false,
      response: {
        content: [{ type: "text", text: `❌ Project ID '${suppliedProjectId}' bukan milik workspace ini.` }],
        isError: true,
      },
    }
  }

  return { ok: true, projectId: ownProjectId }
}

export interface HttpCheckInput {
  path?: string
  expectedText?: string
  expectedContentType?: string
  expectedSignature?: string
  expectedChecksum?: string
}

export interface HttpCheckResult {
  path: string
  url: string
  status: number
  ok: boolean
  htmlLength: number
  containsExpectedText?: boolean
  looksLikeErrorPage: boolean
  contentType?: string
  contentTypeOk?: boolean
  signatureOk?: boolean
  checksumOk?: boolean
}

/**
 * Runs one or more HTTP-level checks against a base URL — shared by
 * verify_deployment_url (checks the PRODUCTION domain) and
 * promote_deployment (checks a staging CANDIDATE's own URL before deciding
 * whether it's safe to promote). Never throws per-check: a fetch failure
 * becomes `ok: false` with status 0, same as the other failure modes, so
 * one bad check doesn't abort the whole batch.
 */
export async function runHttpChecks(baseUrl: string, checks: HttpCheckInput[]): Promise<HttpCheckResult[]> {
  const base = baseUrl.replace(/\/$/, "")
  return Promise.all(checks.map(async (check) => {
    const targetUrl = check.path ? `${base}${check.path.startsWith("/") ? check.path : `/${check.path}`}` : base
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 15000)
    try {
      const res = await safeFetch(targetUrl, {
        method: "GET",
        signal: controller.signal,
        headers: { "User-Agent": "SaCMS-MCP-Verify/1.0" },
      })
      // Read raw bytes once — needed for a binary signature/checksum
      // check, and HTML substring matching works the same off the
      // decoded text either way.
      const bytes = Buffer.from(await res.arrayBuffer().catch(() => new ArrayBuffer(0)))
      const html = bytes.toString("utf-8")
      const containsExpectedText = check.expectedText ? html.includes(check.expectedText) : undefined
      const contentType = res.headers.get("content-type") || ""
      const contentTypeOk = check.expectedContentType ? contentType.includes(check.expectedContentType) : undefined
      // A 200 alone doesn't mean a binary asset is actually valid —
      // confirmed live (chatgpt3.md): a corrupted icon still passed
      // a plain status check.
      const signatureOk = check.expectedSignature ? matchesSignature(check.expectedSignature, bytes) : undefined
      const checksumOk = check.expectedChecksum
        ? createHash("sha256").update(bytes).digest("hex") === check.expectedChecksum
        : undefined
      // Heuristic only, not exhaustive — catches Vercel's own protection/
      // not-found boilerplate; the frontend's OWN 404/error page (if it
      // has one) is a real rendered page and isn't flagged by this, by
      // design — that's a route the caller itself built and should check
      // with its own expectedText instead.
      const looksLikeErrorPage = /DEPLOYMENT_NOT_FOUND|This deployment is protected|Authentication Required/i.test(html)
      const ok = res.ok && !looksLikeErrorPage
        && (containsExpectedText ?? true) && (contentTypeOk ?? true) && (signatureOk ?? true) && (checksumOk ?? true)
      return { path: check.path || "/", url: targetUrl, status: res.status, ok, htmlLength: html.length, containsExpectedText, looksLikeErrorPage, contentType, contentTypeOk, signatureOk, checksumOk }
    } catch {
      return { path: check.path || "/", url: targetUrl, status: 0, ok: false, htmlLength: 0, looksLikeErrorPage: false }
    } finally {
      clearTimeout(timeoutId)
    }
  }))
}

/**
 * Resolves which deployment a read-only deployment-scoped tool should act
 * on: the caller's own id (ownership-checked — a deploymentId alone carries
 * no tenant scoping) or, when omitted, this workspace's latest production
 * deployment. Shared by get_deployment_status, get_deployment_source, and
 * get_deployment_build_logs so a lost deploy_to_sacms response never leaves
 * an agent stuck with no way to recover an id. When resolved via the
 * fallback path, `status` is already known (from the same lookup that
 * found the deployment) so get_deployment_status doesn't need a second
 * Vercel API call just to re-fetch what it already has.
 */
export async function resolveDeploymentId(
  auth: AuthContext,
  suppliedId: string | undefined,
): Promise<
  | { ok: true; id: string; status?: { state: string; deploymentUrl: string; productionUrl: string | null; projectId?: string } }
  | { ok: false; response: { content: { type: "text"; text: string }[]; structuredContent: Record<string, unknown>; isError: true } }
> {
  const tenant = await db.tenant.findUnique({ where: { id: auth.tenantId }, select: { vercelProjectId: true } })

  if (suppliedId) {
    const status = await getDeploymentStatus(suppliedId)
    if (status.projectId && tenant?.vercelProjectId && tenant.vercelProjectId !== status.projectId) {
      return {
        ok: false,
        response: {
          content: [{ type: "text", text: `❌ Deployment '${suppliedId}' bukan milik workspace ini.` }],
          structuredContent: { ok: false, code: "FORBIDDEN", message: "Deployment does not belong to this workspace." },
          isError: true,
        },
      }
    }
    return { ok: true, id: suppliedId, status }
  }

  if (!tenant?.vercelProjectId) {
    return {
      ok: false,
      response: {
        content: [{ type: "text", text: "❌ Belum ada deployment project untuk workspace ini. Deploy dulu dengan deploy_to_sacms." }],
        structuredContent: { ok: false, code: "NOT_FOUND", message: "No deployment project yet." },
        isError: true,
      },
    }
  }
  const latest = await getLatestDeployment(tenant.vercelProjectId)
  if (!latest) {
    return {
      ok: false,
      response: {
        content: [{ type: "text", text: "❌ Tidak ditemukan riwayat deployment untuk workspace ini di Vercel." }],
        structuredContent: { ok: false, code: "NOT_FOUND", message: "No deployment history found." },
        isError: true,
      },
    }
  }
  return {
    ok: true,
    id: latest.id,
    status: { state: latest.state, deploymentUrl: latest.deploymentUrl, productionUrl: latest.productionUrl, projectId: tenant.vercelProjectId },
  }
}

/**
 * Shared idempotency pre-check for deploy_to_sacms/deploy_website_patch
 * (chatgpt2.md P1) — three outcomes:
 * - "proceed": no key given, or a fresh/abandoned claim — caller should
 *   deploy normally, advancing `effectiveRunId` (falls back to the
 *   caller's own `runId` if one was also given) once it has a result.
 * - "replay": this exact key already completed a deploy — return that
 *   recorded result instead of deploying again.
 * - "in_progress": another request with this exact key is still mid-flight
 *   (claimed recently, no deploymentId yet) — don't start a second deploy.
 */
export async function resolveIdempotency(
  auth: AuthContext,
  idempotencyKey: string | undefined,
  intent: "create" | "update",
): Promise<
  | { kind: "proceed"; effectiveRunId: string | undefined }
  | { kind: "replay"; run: McpBuildRunRecord; status: { state: string; deploymentUrl: string; productionUrl: string | null } | null }
  | { kind: "in_progress"; run: McpBuildRunRecord }
> {
  if (!idempotencyKey) return { kind: "proceed", effectiveRunId: undefined }

  const { run, isNew } = await findOrClaimByIdempotencyKey(auth.tenantId, idempotencyKey, intent)
  if (isNew) return { kind: "proceed", effectiveRunId: run.id }
  if (run.deploymentId) {
    const status = await getDeploymentStatus(run.deploymentId).catch(() => null)
    return { kind: "replay", run, status }
  }
  if (isIdempotencyClaimStillInFlight(run)) return { kind: "in_progress", run }
  return { kind: "proceed", effectiveRunId: run.id }
}

// ─── Content entry write context ───────────────────────────────────────────
// Builds the (ctx, actor) pair entry-service.ts needs — the same service
// layer the dashboard's create/updateEntryAction now goes through, so MCP's
// content-entry write tools inherit draftTemplateId filtering, schema/
// relation validation, and optimistic-locking for free instead of
// reimplementing (and drifting from) that logic with raw Prisma calls.
// MCP tokens aren't tied to a human actor or role, so "system" is the right
// actor kind: it bypasses the staff/member ownership checks (there's no
// per-entry "owner" concept for a workspace-wide token) and the workflow-
// transition gate, same as super-admin global content and cron already do.
export async function mcpEntryContext(auth: AuthContext, tenantDb: Awaited<ReturnType<typeof getTenantDb>>): Promise<{ ctx: EntryWriteContext; actor: ContentActor }> {
  return {
    ctx: { client: tenantDb, tenantId: auth.tenantId, tenantSlug: auth.tenantSlug, isGlobal: false, enforcePlan: true },
    actor: { kind: "system" },
  }
}

// ─── Slug Normalization ───────────────────────────────────────────────────────

/**
 * Normalizes any input into the same slug shape the manual UI forms enforce
 * via regex (/^[a-z0-9][a-z0-9-]*$/) — the ad hoc per-tool `.replace(...)`
 * calls this replaces could still produce a slug starting with "-" or
 * containing "_", inconsistent with (and looser than) anything created by
 * hand through the Developer Portal.
 */
export function toSafeSlug(input: string, fallback = "item"): string {
  const slug = input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
  return slug || fallback
}

// ─── Relational Dependency Guards ──────────────────────────────────────────────
// Mirror the checks in src/actions/{content-types,single-types,components}.ts
// so an MCP delete tool can't silently leave a relation/component field
// dangling — unlike the Developer Portal UI, an agent calling these tools
// gets no confirmation dialog, so the guard has to be the thing that stops it.

export type TenantPrismaClient = Awaited<ReturnType<typeof getTenantDb>>

export async function checkRelationDependents(
  tenantDb: TenantPrismaClient,
  tenantId: string,
  targetSlug: string,
  exclude: { contentTypeId: string } | { singleTypeId: string },
): Promise<{ fieldName: string; parentName: string } | null> {
  const fields = await tenantDb.schemaField.findMany({
    where: {
      relationSlug: targetSlug,
      NOT: exclude,
      OR: [
        { contentType: { tenantId } },
        { singleType: { tenantId } },
        { component: { tenantId } },
        { contentType: { tenantId: null } },
        { singleType: { tenantId: null } },
        { component: { tenantId: null } },
      ],
    },
    include: { contentType: true, singleType: true, component: true },
  })
  if (fields.length === 0) return null
  const f = fields[0]
  return {
    fieldName: f.name,
    parentName: f.contentType?.name || f.singleType?.name || f.component?.name || "skema lain",
  }
}

export async function countComponentDependents(
  tenantDb: TenantPrismaClient,
  tenantId: string,
  targetSlug: string,
): Promise<number> {
  const allFields = await tenantDb.schemaField.findMany({
    where: {
      OR: [
        { contentType: { tenantId } },
        { singleType: { tenantId } },
        { component: { tenantId } },
        { contentType: { tenantId: null } },
        { singleType: { tenantId: null } },
        { component: { tenantId: null } },
      ],
    },
    select: { options: true },
  })
  return allFields.filter((field) => {
    if (!field.options) return false
    let parsedOptions: any = field.options
    if (typeof parsedOptions === "string") {
      try {
        parsedOptions = JSON.parse(parsedOptions)
      } catch {
        return false
      }
    }
    return parsedOptions?.componentSlug === targetSlug
  }).length
}

// ─── MCP Handler with Complete CRUD Capabilities ─────────────────────────────

export async function trackWorkspaceOperation(kind: "apply_website_template" | "deploy_site_version" | "deploy_to_sacms", tenantId: string, work: () => Promise<{ isError?: boolean; structuredContent?: unknown; content: { type: string; text: string }[] }>) {
  const operation = await startBackgroundOperation(kind, null, async () => {
    const response = await work()
    const failed = response.isError || (response.structuredContent as { ok?: boolean } | undefined)?.ok === false
    return { failed, result: response.structuredContent, error: failed ? response.content[0]?.text : undefined }
  }, tenantId)
  const structured = { operationId: operation.id, status: "running" as const }
  return { structuredContent: structured, content: [{ type: "text" as const, text: JSON.stringify(structured) }] }
}
